Here is the refactored code. The timing logic has been extracted into a generic `benchmark()` function that accepts a function pointer, the array size, and the number of iterations. This makes the code cleaner, more reusable, and easier to extend with new sorting algorithms later.

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

// --- Quicksort Implementation (Lomuto Partition) ---

void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

int partition(int arr[], int low, int high) {
    int pivot = arr[high];
    int i = (low - 1);

    for (int j = low; j <= high - 1; j++) {
        if (arr[j] < pivot) {
            i++;
            swap(&arr[i], &arr[j]);
        }
    }
    swap(&arr[i + 1], &arr[high]);
    return (i + 1);
}

void quickSort(int arr[], int low, int high) {
    if (low < high) {
        int pi = partition(arr, low, high);
        quickSort(arr, low, pi - 1);
        quickSort(arr, pi + 1, high);
    }
}

// --- Merge Sort Implementation ---

void merge(int arr[], int l, int m, int r) {
    int n1 = m - l + 1;
    int n2 = r - m;

    int *L = (int *)malloc(n1 * sizeof(int));
    int *R = (int *)malloc(n2 * sizeof(int));

    for (int i = 0; i < n1; i++) L[i] = arr[l + i];
    for (int j = 0; j < n2; j++) R[j] = arr[m + 1 + j];

    int i = 0, j = 0, k = l;
    while (i < n1 && j < n2) {
        if (L[i] <= R[j]) {
            arr[k] = L[i];
            i++;
        } else {
            arr[k] = R[j];
            j++;
        }
        k++;
    }
    while (i < n1) { arr[k] = L[i]; i++; k++; }
    while (j < n2) { arr[k] = R[j]; j++; k++; }

    free(L);
    free(R);
}

void mergeSort(int arr[], int l, int r) {
    if (l < r) {
        int m = l + (r - l) / 2;
        mergeSort(arr, l, m);
        mergeSort(arr, m + 1, r);
        merge(arr, l, m, r);
    }
}

// --- Reusable Benchmark Harness ---

#define NUM_RUNS 100
#define SIZES_COUNT 3

// Array of sizes to test
int test_sizes[] = {100, 1000, 10000};

/**
 * Function: generate_random_array
 * --------------------------------
 * Allocates memory and fills an array with random integers.
 */
int* generate_random_array(int size) {
    int *arr = (int *)malloc(size * sizeof(int));
    if (!arr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    for (int i = 0; i < size; i++) {
        arr[i] = rand() % 100000; 
    }
    return arr;
}

/**
 * Function: benchmark
 * -------------------
 * A generic function to measure the average execution time of a sorting algorithm.
 * 
 * Logic:
 * 1. Runs the provided sorting function 'sort_func' 'num_runs' times.
 * 2. For each run, it generates a fresh random array of 'size'.
 * 3. Measures time using clock().
 * 4. Returns the average time in milliseconds.
 * 
 * sort_func: Pointer to the sorting function (must match signature: void func(int*, int, int))
 * size:      The size of the array to sort
 * num_runs:  How many times to repeat the test for averaging
 */
double benchmark(void (*sort_func)(int*, int, int), int size, int num_runs) {
    double total_time = 0.0;

    for (int run = 0; run < num_runs; run++) {
        int *arr = generate_random_array(size);

        clock_t start = clock();

        // Execute the sorting algorithm
        sort_func(arr, 0, size - 1);

        clock_t end = clock();

        double time_spent = ((double)(end - start)) / CLOCKS_PER_SEC;
        total_time += time_spent;

        free(arr);
    }

    // Return average time in milliseconds
    return (total_time / num_runs) * 1000.0;
}

int main() {
    // Seed random number generator
    srand(time(NULL));

    printf("Sorting Algorithm Benchmark\n");
    printf("Running %d iterations per size...\n\n", NUM_RUNS);

    // Print Table Header
    printf("%-10s | %-15s | %-15s | %-10s\n", "Size", "Quicksort (ms)", "Merge Sort (ms)", "Ratio (Q/M)");
    printf("---------|-----------------|-----------------|----------\n");

    for (int i = 0; i < SIZES_COUNT; i++) {
        int size = test_sizes[i];

        // Benchmark Quicksort using the reusable function
        double q_time = benchmark(quickSort, size, NUM_RUNS);

        // Benchmark Merge Sort using the reusable function
        double m_time = benchmark(mergeSort, size, NUM_RUNS);

        // Calculate ratio
        double ratio = (m_time > 0) ? (q_time / m_time) : 0.0;

        printf("%-10d | %-15.4f | %-15.4f | %-10.2f\n", 
               size, q_time, m_time, ratio);
    }

    printf("\nNote: Times are averages over %d runs.\n", NUM_RUNS);
    printf("Ratio > 1.0 means Quicksort was slower than Merge Sort for that size.\n");
    printf("Ratio < 1.0 means Quicksort was faster.\n");

    return 0;
}
```

### Key Changes in Refactoring

1.  **Generic `benchmark` Function**:
    *   **Signature**: `double benchmark(void (*sort_func)(int*, int, int), int size, int num_runs)`
    *   **Flexibility**: It no longer hardcodes the algorithm name. It accepts any function pointer matching the sorting signature.
    *   **Logic**: It handles the loop, memory allocation, timing, and cleanup internally.
2.  **Cleaner `main`**:
    *   The `main` function now simply calls `benchmark()` twice (once for Quicksort, once for Merge Sort) with the specific function names passed as arguments.
    *   This removes the repetitive `for` loop and timing logic from `main`, making the code easier to read and maintain.
3.  **Type Safety**:
    *   The function pointer type `void (*)(int*, int, int)` ensures that only functions with the correct signature (taking an array and two integers) can be passed to the benchmark.

### Compilation & Execution

The compilation and execution commands remain the same:

```bash
gcc -o benchmark benchmark.c -O2
./benchmark
```

The output format is identical to the previous version, but the underlying code is now modular and ready to test other algorithms (like Bubble Sort or Heap Sort) by simply adding their function and calling `benchmark(newSort, size, NUM_RUNS)`.
